mapper.insert:
insert into temp_inner_car(tic_id, car_num, start_time, end_time, config_id, fee_name, community_id, pa_id, pa_num, remark, status_cd
                            )
values (#{ticId}, #{carNum}, #{startTime}, #{endTime}, #{configId}, #{feeName}, #{communityId}, #{paId}, #{paNum}, #{remark}, #{statusCd}
        )

mapper.select:
select t.tic_id,t.tic_id ticId,t.car_num,t.car_num
carNum,t.start_time,t.start_time startTime,t.end_time,t.end_time
endTime,t.config_id,t.config_id configId,t.fee_name,t.fee_name
feeName,t.community_id,t.community_id communityId,t.pa_id,t.pa_id paId,t.pa_num,t.pa_num paNum,t.remark,t.status_cd,t.status_cd statusCd,t.create_time createTime
from temp_inner_car t
where 1 =1

    and t.tic_id= #{ticId}


    and t.car_num= #{carNum}


    and t.start_time= #{startTime}


    and t.end_time= #{endTime}


    and t.end_time > now()
    and t.start_time < now()


    and t.config_id= #{configId}


    and t.fee_name= #{feeName}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.pa_id= #{paId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update temp_inner_car t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.car_num= #{carNum}


    , t.start_time= #{startTime}


    , t.end_time= #{endTime}


    , t.config_id= #{configId}


    , t.fee_name= #{feeName}


    , t.pa_id= #{paId}


    , t.pa_num= #{paNum}


    , t.remark= #{remark}

where 1=1

    and t.tic_id= #{ticId}


    and t.community_id= #{communityId}

